--------------------------------------------------------------------------------
---- MACSHELL LIQUID GLASS NOTIFICATIONS & SAFE ERROR HANDLER               ----
--------------------------------------------------------------------------------

local function notify_msg(title, message, icon, urgency)
    local clean_title = tostring(title or "Hyprland"):gsub("'", "\\'"):gsub("\n", " ")
    local clean_msg = tostring(message or ""):gsub("'", "\\'"):gsub("\n", " ")
    clean_msg = clean_msg:gsub("^%s*=%[C%]:%-1:%s*", "")
    clean_msg = clean_msg:gsub("^%s*.-:%d+:%s*", "")
    clean_msg = clean_msg:gsub("^error:%s*", "")
    local ico = icon or "preferences-system-windows"
    local urg = urgency or "normal"
    hl.dispatch(hl.dsp.exec_cmd(string.format("notify-send -a 'MacShell' -u %s -i %s '%s' '%s'", urg, ico, clean_title, clean_msg)))
end

local function notify_error(title, message)
    notify_msg(title or "Hyprland Notice", message, "dialog-error", "critical")
end

local function safe_dispatch(action, context)
    local ok, err = pcall(function()
        hl.dispatch(action)
    end)
    if not ok then
        notify_error(context or "Action Notice", err)
    end
    return ok
end

-- Protect all function-based keybindings globally: any runtime error is routed to MacShell Liquid Glass notifications
local orig_hl_bind = hl.bind
hl.bind = function(key, action, opts)
    if type(action) == "function" then
        local safe_fn = function(...)
            local args = { ... }
            local ok, err = xpcall(function() return action(table.unpack(args)) end, debug.traceback)
            if not ok then
                local short_err = tostring(err):match("([^\n]+)") or tostring(err)
                short_err = short_err:gsub("^[./\\]+[%w_./\\]+:%d+:%s*", ""):gsub("error:%s*=%[C%]:%-1:%s*", "")
                notify_error("Keybind Notice (" .. tostring(key) .. ")", short_err)
            end
        end
        return orig_hl_bind(key, safe_fn, opts)
    else
        return orig_hl_bind(key, action, opts)
    end
end

