-- Super + J: Layout split toggle (dwindle: togglesplit, scrolling: promote / split stacked window)
hl.bind(mainMod .. " + J", function()
    local cur = tostring(hl.get_config("general:layout") or ""):gsub("%s+", "")
    if cur == "scrolling" then
        -- In Infinite Scrolling: promote stacked window into its own column
        safe_dispatch(hl.dsp.layout("promote"), "Infinite Scrolling")
    else
        safe_dispatch(hl.dsp.layout("togglesplit"), "Dwindle Layout")
    end
end)

-- Toggle between Dwindle and Niri-style Infinite Scrolling globally across all workspaces
hl.bind(mainMod .. " + F", function()
    local cur = tostring(hl.get_config("general:layout") or ""):gsub("%s+", "")
    local target = (cur == "scrolling") and "dwindle" or "scrolling"

    -- Apply layout globally for current and future workspaces
    hl.config({ general = { layout = target } })

    -- Force Hyprland to immediately retile all windows, tabs, and applications across all workspaces
    hl.exec_scheduled_prop_refresh_immediately()

    local label = (target == "scrolling") and "Infinite Scrolling (Niri)" or "Dwindle Layout"
    -- Display using MacShell's native Liquid Glass notification card
    notify_msg("Layout Switched", label, "preferences-system-windows", "normal")
end)

-- Safe dispatcher that only sends scrolling layout messages when in scrolling mode
local function scroll_layoutmsg(msg)
    return function()
        local cur = tostring(hl.get_config("general:layout") or ""):gsub("%s+", "")
        if cur == "scrolling" then
            safe_dispatch(hl.dsp.layout(msg), "Scrolling Layout")
        end
    end
end

-- Niri-style column resize (cycle width: 33% -> 50% -> 66% -> 100%)
-- Restores the exact original lengths and native speed:
-- - Tiled windows: uses native C++ colresize (+conf / -conf) in scrolling mode (33% -> 50% -> 66% -> 100%)
-- - Floating windows (e.g. MacShell Settings): snaps dynamically across the exact same original 33% -> 50% -> 66% -> 100% lengths
local function handle_window_resize(step)
    return function()
        local win = hl.get_active_window()
        if win and win.floating then
            local mon = hl.get_active_monitor()
            local mw = mon and mon.width or 1600
            local mh = mon and mon.height or 900
            local cur_w = win.size and win.size.x or 800

            -- Original exact Niri column lengths: 33.3%, 50%, 66.7%, 100%
            local orig_widths = {
                math.floor(mw * 0.333),
                math.floor(mw * 0.500),
                math.floor(mw * 0.667),
                mw - 24,
            }

            local idx = 1
            local min_diff = math.abs(cur_w - orig_widths[1])
            for i = 2, #orig_widths do
                local diff = math.abs(cur_w - orig_widths[i])
                if diff < min_diff then
                    min_diff = diff
                    idx = i
                end
            end

            local next_idx = (step > 0) and ((idx % #orig_widths) + 1) or (idx - 1)
            if next_idx < 1 then next_idx = #orig_widths end

            local target_w = orig_widths[next_idx]
            local target_h = mh - 70
            local x = math.floor((mw - target_w) / 2)
            local y = 30 + math.floor((mh - 30 - target_h) / 2)

            hl.dispatch(hl.dsp.window.resize({ x = target_w, y = target_h, relative = false }))
            hl.dispatch(hl.dsp.window.move({ x = x, y = y }))
        else
            -- Original native scrolling colresize (instant & exact)
            local cur = tostring(hl.get_config("general:layout") or ""):gsub("%s+", "")
            if cur == "scrolling" then
                local cmd = (step > 0) and "colresize +conf" or "colresize -conf"
                safe_dispatch(hl.dsp.layout(cmd), "Column Resize")
            end
        end
    end
end

