-- Move window with mainMod + SHIFT + arrow keys (swaps columns on left/right in scrolling mode)
local function handle_shift_arrow(dir, scroll_cmd)
    return function()
        local cur = tostring(hl.get_config("general:layout") or ""):gsub("%s+", "")
        if cur == "scrolling" and scroll_cmd then
            safe_dispatch(hl.dsp.layout(scroll_cmd), "Swap Column")
        else
            safe_dispatch(hl.dsp.window.move({ direction = dir }), "Move Window")
        end
    end
end

hl.bind(mainMod .. " + SHIFT + left",  handle_shift_arrow("left",  "swapcol l"))
